{
  "name": "通用SCPI仪器",
  "name_en": "Generic SCPI Instrument",
  "manufacturer": "",
  "description": "支持SCPI命令控制的通用实验室电子仪器，可代表频谱仪、信号源、示波器、源表等多种台式测量设备。此类仪器常用于实验室自动化测试、参数配置、状态查询和测量数据采集。",
  "description_en": "A generic laboratory electronic instrument that accepts SCPI commands. It can represent many benchtop test and measurement devices, such as spectrum analyzers, signal generators, oscilloscopes, or source meters, and is commonly used for automated testing, parameter configuration, status queries, and measurement data acquisition in laboratories.",
  "tag_hints": [
    "SCPI control",
    "test and measurement",
    "lab automation",
    "remote instrument control",
    "benchtop instrument"
  ],
  "actions": [
    {
      "action_name": "auto-close",
      "description": "关闭与仪器的通信连接。",
      "description_en": "Close the communication connection to the instrument."
    },
    {
      "action_name": "auto-query",
      "description": "向仪器发送查询命令并读取返回结果。",
      "description_en": "Send a query command to the instrument and read back the response."
    },
    {
      "action_name": "auto-set_opc_timeout",
      "description": "设置等待仪器操作完成（OPC）的超时时间和轮询间隔。",
      "description_en": "Set the timeout and polling interval used while waiting for instrument operation complete (OPC)."
    },
    {
      "action_name": "auto-wait_opc",
      "description": "等待仪器完成当前操作。",
      "description_en": "Wait for the instrument to complete the current operation."
    },
    {
      "action_name": "auto-write",
      "description": "向仪器写入SCPI命令。",
      "description_en": "Send an SCPI command to the instrument."
    }
  ]
}

